function normalizeAddress(value) { return String(value ?? "").toLowerCase().replace(/\b(apartment|apt|unit|suite|ste)\b/g, "").replace(/\b(street|st|road|rd|avenue|ave|drive|dr|court|ct|boulevard|blvd|lane|ln|circle|cir|place|pl|terrace|ter)\b/g, "").replace(/[^a-z0-9]/g, ""); }
function cleanSubject(s) { return String(s || "").replace(/^(\s*(fwd|fw|re)\s*:\s*)+/i, "").trim(); }

const emails = $items("Gmail Trigger").map(i => i.json || {});
const sheetRows = $items("Read Properties").map(i => i.json || {});
const settingsRows = $items("Read Settings").map(i => i.json || {});
const appRows = $items("Read Rental Applications").map(i => i.json || {});

const settings = {};
for (const row of settingsRows) if (row.key) settings[row.key] = row.value;

const stage = settings.rental_application_stage || "Tenant Inquiry Lead (Do Not Contact)";
const alertPhone = settings.rental_application_alert_phone || "";
const fromNumber = settings.from_number || "";

const results = [];

for (const email of emails) {
  const messageId = email.id || email.messageId || "";
  const rawSubject = email.Subject || email.subject || "";

  const skip = (reason, extra) => ({ json: { skip: true, reason, message_id: messageId, raw_subject: rawSubject, alert_phone: alertPhone, from_number: fromNumber, ...(extra || {}) } });

  if (!messageId) { results.push(skip("no_message_id")); continue; }

  // Idempotency: a redelivered/re-synced Gmail item must not create a second
  // FUB person. message_id is the natural key.
  if (appRows.some(r => String(r.message_id ?? "") === messageId)) {
    results.push(skip("duplicate_message"));
    continue;
  }

  const subject = cleanSubject(rawSubject);

  // Defense in depth — the Gmail search query already filters sender +
  // subject, this just guards against an unexpected match.
  if (!/new rental application/i.test(subject)) {
    results.push(skip("not_a_rental_application_email"));
    continue;
  }

  const body = String(email.textPlain || email.text || email.snippet || "").replace(/\r\n/g, "\n");

  let address = "";
  const subjMatch = subject.match(/new rental application for\s+(.+?)\s*!?\s*$/i);
  if (subjMatch) address = subjMatch[1].trim();

  let applicantName = "";
  let bodyAddress = "";
  const altMatch = body.match(/^([A-Z][^\n.]*?) completed an application for\s+([^\n.]+)\./m);
  if (altMatch) { applicantName = altMatch[1].trim(); bodyAddress = altMatch[2].trim(); }
  if (!applicantName) {
    const bodyMatch = body.match(/([A-Z][^\n.]*?) has completed their rental application for\s+([^\n,]+),/);
    if (bodyMatch) { applicantName = bodyMatch[1].trim(); bodyAddress = bodyAddress || bodyMatch[2].trim(); }
  }
  if (!address) address = bodyAddress;

  // A real rental-application email we failed to parse is a silent-loss risk
  // (no FUB person, nobody notified). Don't drop it — flag it for a human
  // instead, same discipline as the unmatched-address alert elsewhere.
  if (!address || !applicantName) {
    results.push(skip("no_address_or_name_parsed"));
    continue;
  }

  let reviewLink = "";
  const linkMatch = body.match(/(https:\/\/www\.zillow\.com\/rental-manager\/applications\/[^\s>]+)/);
  if (linkMatch) reviewLink = linkMatch[1];

  const nameParts = applicantName.split(/\s+/).filter(Boolean);
  const firstName = nameParts[0] || "Unknown";
  const lastName = nameParts.slice(1).join(" ") || "Applicant";

  // The single place the test gate is applied — same convention as the rest
  // of the chain (see Resolve Inquiry / Check Guards). Making this always
  // true is how the gate gets removed at launch.
  const isTestLead = firstName === "Test";
  const testGateOpen = true; // TEST GATE LIFTED (was: isTestLead)

  // Match against Properties for logging/context only — never blocks
  // creation. Andrew's ask was "just create the person and reference the
  // address"; an unmatched address here just means Properties needs a row,
  // same as the existing inquiry flow's unmatched case.
  const normalizedAddr = normalizeAddress(address);
  const matches = [];
  for (const row of sheetRows) {
    const naf = normalizeAddress(row.street_address || "");
    const nak = normalizeAddress(row.property_key || "");
    let score = 0;
    if (naf && naf === normalizedAddr) score += 120;
    else if (nak && nak === normalizedAddr) score += 90;
    else if (naf && (naf.includes(normalizedAddr) || normalizedAddr.includes(naf))) score += 20;
    if (score > 0) matches.push({ ...row, score });
  }
  matches.sort((a, b) => b.score - a.score);
  const best = matches[0] || null;
  const matched = !!best && best.score >= 80;
  const match_status = matched ? "matched" : "unmatched";
  const canonicalAddress = matched ? (best.street_address || address) : address;

  results.push({ json: {
    skip: false,
    is_test_lead: isTestLead,
    test_gate_open: testGateOpen,
    message_id: messageId,
    received_at: email.date || new Date().toISOString(),
    applicant_name: applicantName,
    first_name: firstName,
    last_name: lastName,
    property_address: address,
    canonical_address: canonicalAddress,
    property_key: matched ? (best.property_key || "") : "",
    match_status,
    review_link: reviewLink,
    fub_source: "Zillow Rental Manager",
    fub_stage: stage,
    alert_phone: alertPhone,
    from_number: fromNumber,
    logged_at: new Date().toISOString(),
  } });
}

return results;

const search = $json;
const people = search.people || [];
const existing = people[0] || null;
// ── TRASH_TAG_GATE_MARKER: tag-based trash gate (replaces the old stage=="trash" check) ──
// See docs/n8n-workflows.md "FUB Trash-tag gate".
// Requires FUB - Search Existing Person's URL to include &fields=allFields so
// tags/customTrashDate come through (tags alone already do on list endpoints;
// customTrashDate does not without it).
const tagsLower = (existing?.tags || []).map((t) => String(t).trim().toLowerCase());
// ── DATELESS_TRASH_TAG_MARKER ────────────────────────────────────────────────────────────
// Same hole as the other trash-gate nodes; see the Identity Gate's copy.
const rawTrashDateMs = existing ? new Date(existing.customTrashDate || "").getTime() : NaN;
const hasAnyTrashTag = ["permanent trash", "no response trash", "denied credit"].some((t) => tagsLower.includes(t));
const trashDateMs = Number.isFinite(rawTrashDateMs) ? rawTrashDateMs : (existing && hasAnyTrashTag ? Date.now() : NaN);
const daysSinceTrash = Number.isFinite(trashDateMs) ? (Date.now() - trashDateMs) / 86400000 : Infinity;
let existingTrashReason = null;
if (existing) {
  if (tagsLower.includes("permanent trash")) existingTrashReason = "trash_permanent";
  else if (tagsLower.includes("denied credit")) { if (daysSinceTrash <= 365) existingTrashReason = "trash_denied_credit"; }
  else if (tagsLower.includes("no response trash")) { if (daysSinceTrash <= 90) existingTrashReason = "trash_temporary"; } // TRASH_TAG_RENAME_MARKER: real tag is "No Response Trash"
  // ── TRASH_FALLTHROUGH_MARKER: stage fallback must run whenever no TAG produced a block.
  if (!existingTrashReason && ["trash", "permanent trash", "cold rental lead 1 month hold"].includes(String(existing.stage ?? "").trim().toLowerCase())) existingTrashReason = "trash_untagged_fallback";
}
const existingTrashed = !!existingTrashReason;
return [{ json: {
  existing_found: !!existing,
  existing_trashed: existingTrashed,
  existing_trash_reason: existingTrashReason || "",
  existing_person_id: existing ? String(existing.id) : "",
  existing_stage: existing ? (existing.stage || "") : "",
} }];

// ── APPLICATION_ALERT_CC_MARKER ────────────────────────────────────────────────────────────
// One item per recipient: the Twilio node reads its IMMEDIATE input, so N
// items make it send N texts. Never comma-separate a Twilio "To" (21211).
const ins = $input.all();
// Index-align against the source node when the counts match (multi-email-per-
// poll is possible but has never been observed); otherwise fall back to the
// first item and say so, rather than silently pairing the wrong application.
const pick = (arr, i) => {
  if (arr.length === ins.length) return arr[i];
  if (i === 0 && arr.length !== ins.length) {
    console.log("[application-alert-cc] item-count mismatch: input=" + ins.length +
      " source=" + arr.length + " — falling back to the first source item");
  }
  return arr[0];
};

const settings = {};
$('Read Settings').all().forEach((it) => { const r = it.json || {}; if (r.key) settings[r.key] = r.value; });

// Nicole (alert_phone, resolved upstream) PLUS the CC list. An empty CC means
// Nicole only — unlike Build Inquiry Alert, this alert has no off switch.
const last10 = (s) => String(s ?? "").replace(/[^0-9]/g, "").slice(-10);
const buildRecipients = (primary) => {
  const cc = String(settings.alert_cc_phones || "").split(",").map((s) => s.trim()).filter(Boolean);
  const out = [];
  const seen = {};
  [String(primary || "").trim()].concat(cc).forEach((p) => {
    if (!p) return;
    const k = last10(p);
    if (!k || seen[k]) return;
    seen[k] = 1;
    out.push(p);
  });
  return out;
};

const parsed = $('Parse & Resolve Application').all();
const matched = $('Check Existing Match').all();
const out = [];

ins.forEach((_, i) => {
  const d = pick(parsed, i).json;
  const m = pick(matched, i).json;
  const recipients = buildRecipients(d.alert_phone);
  const fromNumber = String(d.from_number || "").trim();
  if (!recipients.length) { console.log("[application-alert-cc] existing-match: no recipients — not sending"); return; }
  if (!fromNumber) { console.log("[application-alert-cc] existing-match: no from_number — not sending (Twilio 21603)"); return; }

  // Template preserved verbatim from the original Twilio node.
  const message =
    "RF: Zillow rental application from " + d.applicant_name + " for " + d.canonical_address +
    " matches an EXISTING FUB person #" + m.existing_person_id + " (\"" + m.existing_stage +
    "\"). No duplicate created — review manually." +
    (d.review_link ? " Review: " + d.review_link : "");

  console.log("[application-alert-cc] existing-match for " + d.applicant_name + " -> " + recipients.length + " recipient(s)");
  recipients.forEach((phone) => out.push({ json: {
    message: message, alert_phone: phone, from_number: fromNumber,
    applicant_name: d.applicant_name, alert_kind: "existing_match",
    sent_at: new Date().toISOString(),
  } }));
});
return out;

