// APPLICATION_INQUIRY_ROW_MARKER
// Runs once per application (runOnceForEachItem). Input is the FUB note
// response, whose personId is the applicant either branch just landed on.
// Resolves the property's cal_link from Read Properties directly, so that
// Parse & Resolve Application does not have to be edited.

const note = $json || {};
const app = $('Parse & Resolve Application').item.json || {};

const norm = (x) => String(x ?? '').trim().toLowerCase();
const personId = note.personId ?? note.person_id ?? '';
const propertyKey = String(app.property_key ?? '').trim();
const matchStatus = norm(app.match_status);

const out = {
  application_inquiry_row_marker: true,
  skip: false,
  reason: '',
  person_id: String(personId ?? ''),
  property_key: propertyKey,
  cal_link: '',
  property_address: app.property_address ?? '',
  property_status: '',
  match_status: app.match_status ?? '',
  message_id: app.message_id ?? '',
  received_at: app.received_at ?? '',
  applicant_name: app.applicant_name ?? '',
};

const bail = (reason) => {
  out.skip = true;
  out.reason = reason;
  console.log('[application-inquiry-row] skip ' + reason +
    ' person=' + out.person_id + ' key=' + out.property_key +
    ' message_id=' + out.message_id);
  return { json: out };
};

if (!personId) return bail('no_person_id');
if (!propertyKey) return bail('no_property_key');
if (matchStatus !== 'matched') return bail('match_status:' + (out.match_status || 'empty'));

const props = $items('Read Properties').map((i) => i.json || {});
const prop = props.find((p) => norm(p.property_key) === norm(propertyKey));
if (!prop) return bail('property_row_not_found');

const calLink = String(prop.cal_link ?? '').trim();
if (!calLink) return bail('property_has_no_cal_link');

out.cal_link = calLink;
// Recorded for the log only. Availability is deliberately NOT checked here:
// the sweep has never checked it either, and inventing that policy in this one
// place would make application-sourced rows behave unlike inquiry-sourced ones.
out.property_status = String(prop.status_override || prop.status || '').trim();

console.log('[application-inquiry-row] candidate person=' + out.person_id +
  ' key=' + out.property_key + ' status=' + out.property_status +
  ' message_id=' + out.message_id);

return { json: out };

// APPLICATION_INQUIRY_ROW_MARKER
// Runs once for all applications in this execution. Emits one Inquiries row per
// application that needs one; emits nothing (and the chain stops) otherwise.

const norm = (x) => String(x ?? '').trim().toLowerCase();
const candidates = $items('Build Application Inquiry (Pre)').map((i) => i.json || {});
const readItems = $items('Read Inquiries (App Dedup)').map((i) => i.json || {});

// FAIL CLOSED. onError:continueRegularOutput turns a Sheets failure into an
// item carrying `error`. Without the tab we cannot prove a row is not already
// there, and appending blind would text a customer the same cal link twice.
const readFailed = readItems.some((r) => r && r.error !== undefined && r.person_id === undefined);
if (readFailed) {
  console.log('[application-inquiry-row] ABORT: Inquiries read unavailable (' +
    JSON.stringify(readItems[0] && readItems[0].error) + '). ' +
    candidates.length + ' application(s) not recorded — repair by hand.');
  return [];
}

const existing = readItems.filter((r) => r && r.person_id !== undefined);
const rows = [];

for (const c of candidates) {
  if (c.skip) continue;

  const eventId = 'application-' + String(c.message_id ?? '');

  // Idempotency against a Gmail redelivery of the same application.
  if (existing.some((r) => norm(r.event_id) === norm(eventId))) {
    console.log('[application-inquiry-row] skip already_recorded event_id=' + eventId);
    continue;
  }

  // A lead who inquired on this property AND applied for it already has a row
  // that the sweep will serve. A second one would send the same link twice.
  if (existing.some((r) => String(r.person_id ?? '').trim() === String(c.person_id).trim() &&
                           norm(r.property_key) === norm(c.property_key))) {
    console.log('[application-inquiry-row] skip existing_row_for_person_and_property person=' +
      c.person_id + ' key=' + c.property_key);
    continue;
  }

  // Guard against two applications in ONE execution for the same pair.
  if (rows.some((r) => r.person_id === String(c.person_id).trim() &&
                       norm(r.property_key) === norm(c.property_key))) {
    console.log('[application-inquiry-row] skip duplicate_within_execution person=' + c.person_id);
    continue;
  }

  rows.push({
    application_inquiry_row_marker: true,
    person_id: String(c.person_id).trim(),
    property_key: String(c.property_key).trim(),
    cal_link: String(c.cal_link).trim(),
    // The application's own arrival time, not now(), so the row's age reflects
    // when the lead actually acted.
    inquired_at: c.received_at || new Date().toISOString(),
    link_sent: 'FALSE',
    link_sent_at: '',
    source: 'Zillow Rental Application',
    event_id: eventId,
    property_address: c.property_address ?? '',
    match_status: 'matched',
    // A rental application notification carries no phone or email. These are
    // recorded only for after-the-fact merge detection; the sweep reads the
    // live FUB person for both, so leaving them blank costs nothing.
    phone: '',
    email: '',
    alert_sent: '',
  });
}

console.log('[application-inquiry-row] candidates=' + candidates.length +
  ' existing_rows=' + existing.length + ' appending=' + rows.length);

return rows.map((json) => ({ json }));

function normalizeAddress(value) { return String(value ?? "").toLowerCase().replace(/\b(apartment|apt|unit|suite|ste)\b/g, "").replace(/\b(street|st|road|rd|avenue|ave|drive|dr|court|ct|boulevard|blvd|lane|ln|circle|cir|place|pl|terrace|ter)\b/g, "").replace(/[^a-z0-9]/g, ""); }
function cleanSubject(s) { return String(s || "").replace(/^(\s*(fwd|fw|re)\s*:\s*)+/i, "").trim(); }

const emails = $items("Gmail Trigger").map(i => i.json || {});
const sheetRows = $items("Read Properties").map(i => i.json || {});
const settingsRows = $items("Read Settings").map(i => i.json || {});
const appRows = $items("Read Rental Applications").map(i => i.json || {});

const settings = {};
for (const row of settingsRows) if (row.key) settings[row.key] = row.value;

const stage = settings.rental_application_stage || "Tenant Inquiry Lead (Do Not Contact)";
const alertPhone = settings.rental_application_alert_phone || "";
const fromNumber = settings.from_number || "";

const results = [];

for (const email of emails) {
  const messageId = email.id || email.messageId || "";
  const rawSubject = email.Subject || email.subject || "";

  const skip = (reason, extra) => ({ json: { skip: true, reason, message_id: messageId, raw_subject: rawSubject, alert_phone: alertPhone, from_number: fromNumber, ...(extra || {}) } });

  if (!messageId) { results.push(skip("no_message_id")); continue; }

  // Idempotency: a redelivered/re-synced Gmail item must not create a second
  // FUB person. message_id is the natural key.
  if (appRows.some(r => String(r.message_id ?? "") === messageId)) {
    results.push(skip("duplicate_message"));
    continue;
  }

  const subject = cleanSubject(rawSubject);

  // Defense in depth — the Gmail search query already filters sender +
  // subject, this just guards against an unexpected match.
  if (!/new rental application/i.test(subject)) {
    results.push(skip("not_a_rental_application_email"));
    continue;
  }

  const body = String(email.textPlain || email.text || email.snippet || "").replace(/\r\n/g, "\n");

  let address = "";
  const subjMatch = subject.match(/new rental application for\s+(.+?)\s*!?\s*$/i);
  if (subjMatch) address = subjMatch[1].trim();

  let applicantName = "";
  let bodyAddress = "";
  const altMatch = body.match(/^([A-Z][^\n.]*?) completed an application for\s+([^\n.]+)\./m);
  if (altMatch) { applicantName = altMatch[1].trim(); bodyAddress = altMatch[2].trim(); }
  if (!applicantName) {
    const bodyMatch = body.match(/([A-Z][^\n.]*?) has completed their rental application for\s+([^\n,]+),/);
    if (bodyMatch) { applicantName = bodyMatch[1].trim(); bodyAddress = bodyAddress || bodyMatch[2].trim(); }
  }
  if (!address) address = bodyAddress;

  // A real rental-application email we failed to parse is a silent-loss risk
  // (no FUB person, nobody notified). Don't drop it — flag it for a human
  // instead, same discipline as the unmatched-address alert elsewhere.
  if (!address || !applicantName) {
    results.push(skip("no_address_or_name_parsed"));
    continue;
  }

  let reviewLink = "";
  const linkMatch = body.match(/(https:\/\/www\.zillow\.com\/rental-manager\/applications\/[^\s>]+)/);
  if (linkMatch) reviewLink = linkMatch[1];

  const nameParts = applicantName.split(/\s+/).filter(Boolean);
  const firstName = nameParts[0] || "Unknown";
  const lastName = nameParts.slice(1).join(" ") || "Applicant";

  // The single place the test gate is applied — same convention as the rest
  // of the chain (see Resolve Inquiry / Check Guards). Making this always
  // true is how the gate gets removed at launch.
  const isTestLead = firstName === "Test";
  const testGateOpen = true; // TEST GATE LIFTED (was: isTestLead)

  // Match against Properties for logging/context only — never blocks
  // creation. Andrew's ask was "just create the person and reference the
  // address"; an unmatched address here just means Properties needs a row,
  // same as the existing inquiry flow's unmatched case.
  const normalizedAddr = normalizeAddress(address);
  const matches = [];
  for (const row of sheetRows) {
    const naf = normalizeAddress(row.street_address || "");
    const nak = normalizeAddress(row.property_key || "");
    let score = 0;
    if (naf && naf === normalizedAddr) score += 120;
    else if (nak && nak === normalizedAddr) score += 90;
    else if (naf && (naf.includes(normalizedAddr) || normalizedAddr.includes(naf))) score += 20;
    if (score > 0) matches.push({ ...row, score });
  }
  matches.sort((a, b) => b.score - a.score);
  const best = matches[0] || null;
  const matched = !!best && best.score >= 80;
  const match_status = matched ? "matched" : "unmatched";
  const canonicalAddress = matched ? (best.street_address || address) : address;

  results.push({ json: {
    skip: false,
    is_test_lead: isTestLead,
    test_gate_open: testGateOpen,
    message_id: messageId,
    received_at: email.date || new Date().toISOString(),
    applicant_name: applicantName,
    first_name: firstName,
    last_name: lastName,
    property_address: address,
    canonical_address: canonicalAddress,
    property_key: matched ? (best.property_key || "") : "",
    match_status,
    review_link: reviewLink,
    fub_source: "Zillow Rental Manager",
    fub_stage: stage,
    alert_phone: alertPhone,
    from_number: fromNumber,
    logged_at: new Date().toISOString(),
  } });
}

return results;

const search = $json;
